23	const (
24		// The upload memory buffer is 32 MiB.
25		// It should be kept low, so RAM usage doesn't get out of control.
26		// This is unrelated to maximum upload size limit, which is now set through system setting.
27		MaxUploadBufferSizeBytes = 32 << 20
28		MebiByte                 = 1024 * 1024
29		// ThumbnailCacheFolder is the folder name where the thumbnail images are stored.
30		ThumbnailCacheFolder = ".thumbnail_cache"
31	
32		// defaultJPEGQuality is the JPEG quality used when re-encoding images for EXIF stripping.
33		// Quality 95 maintains visual quality while ensuring metadata is removed.
34		defaultJPEGQuality        = 95
35		maxBatchDeleteAttachments = 100
36		maxImagePixels            = 50_000_000
37	)
