44	// exifCapableImageTypes defines image formats that may contain EXIF metadata.
45	// These formats will have their EXIF metadata stripped on upload for privacy.
46	var exifCapableImageTypes = map[string]bool{
47		"image/jpeg": true,
48		"image/jpg":  true,
49		"image/tiff": true,
50		"image/webp": true,
51		"image/heic": true,
52		"image/heif": true,
53	}
